-- Sacred ReBorn as a Sacred Gear mod. Sacred ReBorn is the work of the Sacred ReBorn Overlookers group (a
-- non-commercial mod group); this mod only re-creates what their exe and data change, on top of Sacred Gear:
--
--   * overlay.txt (generated by tools/reborn_port.py from the ReBorn folder) serves ReBorn's data files (the SRB
--     data, the text) where the game opens the original ones: Sacred Gear applies it when it starts;
--   * abilities_edits.json (generated too) holds the values ReBorn changes in the exe's ability tables (the combat arts
--     and the spells); this file applies them through gear.data.abilities.
--
-- With -gear-auto the mod also checks itself (see the end): Sacred.exe -gear-auto -gear-load=1 -gear-mods=reborn

local function load_edits()
    local text = gear.read('abilities_edits.json')
    if not text then return nil, 'abilities_edits.json is missing' end
    local doc, err = gear.json.decode(text)
    if not doc then return nil, err end
    local edits, count, samples = {}, 0, {}
    for _, table_edits in pairs(doc.tables) do
        for id, fields in pairs(table_edits) do
            local n = tonumber(id)
            if n then
                local e = {}
                for field, pair in pairs(fields) do
                    e[field] = pair[2]
                    count = count + 1
                    if field == 'effect_base' and #samples < 3 then samples[#samples + 1] = {id = n, field = field, value = pair[2]} end
                end
                edits[n] = e
            end
        end
    end
    return edits, count, samples
end

local applied = {count = 0, ok = false}

local function apply_abilities()
    if applied.ok or not gear.config.abilities then return end
    local edits, count, samples = load_edits()
    if not edits then
        print('abilities not applied: ' .. tostring(count))
        applied.ok = true
        return
    end
    local written, problems = gear.data.abilities:apply(edits)
    if not written then
        return      -- the tables are not there yet: again next frame
    end
    applied.ok, applied.count, applied.edits, applied.samples = true, written, count, samples
    print(('ReBorn: %d ability fields written (%d in the table)'):format(written, count))
    for i, p in ipairs(problems or {}) do
        if i <= 5 then print('ReBorn: ' .. p) end
    end
end

-- B12: ReBorn turns a level into a factor in integer tiers of 12 levels (1 up to level 12, 2 up to 24, 3 up to 36, 4 above);
-- vanilla uses (34 L + 8) / (c1 L + c2). The engine asks through the level.factor hook (six places).
-- B13: constants the engine loads inside its hit handlers and difficulty code. ReBorn points those instructions at other
-- constants: the effect scale of the four hit handlers 0.2 -> 1.0; their chance scale 0.01 -> 1.0 in two of them and, in the other two, a
-- float read from code bytes (-3.4022e35: an address typo of ReBorn's, reproduced); the five difficulty factors 1.0 1.34 1.67 2.0 2.34 ->
-- 1.06 1.08 1.10 1.12 1.14; three scales of one function 0.01 -> 0.01, 0.05, 0.05.
local REBORN_CONSTANTS = {
    ['hit.effect_scale'] = {1.0, 1.0, 1.0, 1.0},
    ['hit.chance_scale'] = {-3.4022038704631622e35, -3.4022038704631622e35, 1.0, 1.0},
    ['difficulty.factor'] = {1.06, 1.08, 1.10, 1.12, 1.14},
    ['scale.559BF0'] = {0.01, 0.05, 0.05},
}
gear.on('combat.constant', function(name, vanilla, index)
    if name == 'difficulty.scale' then
        -- ReBorn's appended code divides the 0.01 of one damage scale by 1, 1, 1, 2, 4 for the difficulty levels 0 .. 4
        local d = gear.game.difficulty() or 0
        return vanilla / (d >= 4 and 4 or d == 3 and 2 or 1)
    end
    local list = REBORN_CONSTANTS[name]
    return list and list[index + 1]
end)

local level_handler = gear.on('level.factor', function(level)
    local tier = 1
    if level > 12 then tier = 2 end
    if level > 24 then tier = 3 end
    if level > 36 then tier = 4 end
    return tier
end)

gear.on('load', apply_abilities)
gear.on('frame', function()
    if not applied.ok then apply_abilities() end
end)

---------------------------------------------------------------------------------------------------------------
-- Self test (-gear-auto): the mod loaded, the overlay serves ReBorn's data, ability values read back as ReBorn's.
---------------------------------------------------------------------------------------------------------------
if not gear.auto then return end
local A = gear.auto
local results = {checks = {}, passed = 0, failed = 0}

local function check(name, ok, detail)
    results.checks[#results.checks + 1] = {name = name, ok = ok and true or false, detail = detail}
    if ok then results.passed = results.passed + 1 else results.failed = results.failed + 1 end
    print(('%s %s%s'):format(ok and 'PASS' or 'FAIL', name, detail and (': ' .. tostring(detail)) or ''))
end

gear.task(function()
    check('main menu', A.wait_for_menu(gear.config.timeout_menu))
    local game = A.wait_for_game(gear.config.timeout_game)
    check('game with a hero', game)
    gear.wait(3)
    if gear.config.idle > 0 then gear.wait(gear.config.idle) end

    -- the ability values
    check('abilities applied', applied.ok and applied.count > 0, applied.count)
    local abilities = gear.data.abilities
    local wrong = 0
    for _, s in ipairs(applied.samples or {}) do
        local a = abilities[s.id]
        local v = a and a[s.field]
        local good = v and math.abs(v - s.value) < 1e-4
        check(('ability %d %s reads back as ReBorn'):format(s.id, s.field), good, v)
        if not good then wrong = wrong + 1 end
    end
    local a1000 = abilities[1000]
    if a1000 then
        check('ability names through gear.text', gear.text.get(a1000.name_text) ~= nil, gear.text.get(a1000.name_text))
    end

    -- the overlay: the rule exists, resolves into this mod, and the game opened ReBorn's balance.bin through it
    local info = gear.files.overlay()
    check('overlay rules', info and info.files > 0, info and info.files)
    local path = gear.files.resolve('bin/balance.bin')
    check('balance.bin resolves into the mod', path:lower():gsub('\\', '/'):find('mods/reborn/data', 1, true) ~= nil, path)
    local served = gear.files.served('bin/balance.bin')
    check('the game read balance.bin from the mod', served > 0, served)

    -- the text overlay: ids whose text ReBorn's SRglbl.res adds or changes (text_checks.json, made by tools/text_checks.py
    -- from two runs of tools/textdump; the text depends on the language, so only for the language it was made in)
    local tc = gear.read('text_checks.json')
    tc = tc and gear.json.decode(tc)
    if tc and tc.language == gear.settings.get('LANGUAGE') then
        for _, c in ipairs(tc.checks) do
            check(('text %d is from ReBorn'):format(c.id), gear.text.get(c.id) == c.text, gear.text.get(c.id))
        end
    else
        print('text checks skipped: no text_checks.json for the game language')
    end

    -- the save folder redirect (overlay.txt: saves = save): the game read the savegame it loaded from the mod's folder
    local mine = info and info.saves
    check('saves are redirected to the mod', mine ~= nil, mine)
    local save = gear.files.served('save/game01.pak')
    check('the game read GAME01.PAK from the mod folder', save > 0, save)
    check('a save path resolves into the mod', gear.files.resolve('save/new.pak'):lower():gsub('\\', '/'):find('mods/reborn/save/new.pak', 1, true) ~= nil,
          gear.files.resolve('save/new.pak'))

    -- pictures for a person to look at (the models and items come from the overlay's PAKs when it serves them)
    A.screenshot('reborn-world')
    A.press('i')
    gear.wait(2)
    A.screenshot('reborn-inventory')
    A.press('i')
    gear.wait(1)

    -- the level.factor hook: call the engine's own level function (from a worker thread, so the hook can answer): ReBorn's tiers
    for _, case in ipairs({{5, 1}, {12, 1}, {13, 2}, {24, 2}, {30, 3}, {37, 4}, {80, 4}}) do
        local got
        for attempt = 1, 20 do
            if A.engine_level_factor_start(case[1]) then
                gear.wait_until(function() got = A.engine_level_factor_result(); return got ~= nil end, 3)
                if got ~= nil then break end
            end
            gear.wait(0.1)
        end
        check(('engine level function: level %d gives the tier %d'):format(case[1], case[2]), got == case[2], got)
    end

    -- without the handler the displaced vanilla block runs unchanged: trunc((34 L + 8) / (7 L + 36))
    gear.off(level_handler)
    for _, case in ipairs({{5, 2}, {20, 3}, {100, 4}}) do
        local got
        for attempt = 1, 20 do
            if A.engine_level_factor_start(case[1]) then
                gear.wait_until(function() got = A.engine_level_factor_result(); return got ~= nil end, 3)
                if got ~= nil then break end
            end
            gear.wait(0.1)
        end
        check(('engine level function without a handler: level %d gives the vanilla %d'):format(case[1], case[2]), got == case[2], got)
    end

    -- the stubs of the constant site hooks, on two functions built in memory: answered through a handler of this mod, then vanilla
    local selftest_handler = gear.on('combat.constant', function(name, vanilla)
        if name == 'selftest.fmul' then return vanilla * 10 end
        if name == 'selftest.fld' then return 7.5 end
    end)
    local st
    for attempt = 1, 20 do
        if A.site_hook_selftest_start() then
            gear.wait_until(function() st = A.site_hook_selftest_result(); return st ~= nil end, 3)
            if st ~= nil then break end
        end
        gear.wait(0.1)
    end
    check('constant site stub: fmul answered by a mod (0.2 * 10)', st and math.abs(st.fmul - 2.0) < 1e-4, st and st.fmul)
    check('constant site stub: fld answered by a mod (7.5)', st and math.abs(st.fld - 7.5) < 1e-4, st and st.fld)
    check('constant site stub: eax, ecx and edx survive', st and st.registers_kept, st and tostring(st.registers_kept))
    gear.off(selftest_handler)
    st = nil
    for attempt = 1, 20 do
        if A.site_hook_selftest_start() then
            gear.wait_until(function() st = A.site_hook_selftest_result(); return st ~= nil end, 3)
            if st ~= nil then break end
        end
        gear.wait(0.1)
    end
    check('constant site stub without an answer: the vanilla constants', st and math.abs(st.fmul - 0.2) < 1e-4 and math.abs(st.fld - 0.2) < 1e-4,
          st and (st.fmul .. ' ' .. st.fld))

    -- a fight: creatures next to the hero make the engine's hit code run through the hooks (counters only; informational)
    if gear.config.fight > 0 then
        local hero = gear.world.hero()
        local types = gear.data.object_types:search('wolf', 50)
        local kind
        for _, t in ipairs(types) do if t.kind and t.kind < 4 then kind = t.id; break end end
        if hero and kind then
            local x, y, layer = hero:position()
            for i = 1, 4 do gear.world.spawn(kind, x + 60 * i, y + 40, {layer = layer}) end
            gear.wait(gear.config.fight)
        end
    end

    -- the level.factor hook: the engine's sites were hooked (the counters show whether the game asked meanwhile)
    local hs = gear.hooks.stats('level.factor')
    print(('level.factor hook: %d calls, %d answered, %d busy'):format(hs.calls, hs.answered, hs.busy))
    results.level_factor = hs
    local cs = gear.hooks.stats('combat.constant')
    print(('combat.constant hook: %d calls, %d answered, %d busy'):format(cs.calls, cs.answered, cs.busy))
    results.combat_constant = cs
    check('difficulty level of the running game', (gear.game.difficulty() or -1) >= 0 and gear.game.difficulty() <= 4, gear.game.difficulty())
    check('the level.factor hook answered the engine', hs.answered >= 7, ('%d calls, %d answered, %d busy'):format(hs.calls, hs.answered, hs.busy))

    -- which of the overlay's files the game really opened through it (informational; some are only read in some places)
    local rules = gear.read('overlay.txt') or ''
    local served_files, total = {}, 0
    for line in rules:gmatch('([^' .. string.char(13, 10) .. ']+)') do
        local game = line:match('^%s*([^#=]-)%s*=%s*%S')
        if game and game:lower() ~= 'saves' then
            local n = gear.files.served(game)
            if n > 0 then served_files[game] = n; total = total + 1 end
        end
    end
    results.overlay_served = served_files
    print(('overlay: %d files served to the game'):format(total))
    for game, n in pairs(served_files) do print(('  served %s x%d'):format(game, n)) end

    results.state = A.state()
    A.write('reborn.json', gear.json.encode(results))
    print(('%d passed, %d failed'):format(results.passed, results.failed))
    if gear.config.quit then A.quit(results.failed == 0 and 0 or 1) end
end)
